import { mkdir, readFile, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const siteDirectory = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const sourcePath = resolve(siteDirectory, "..", "install.sh");
const outputPath = resolve(siteDirectory, "app", "yo-setup", "installer.generated.ts");

const installer = await readFile(sourcePath, "utf8");
const generated = [
  "// Generated from ../../install.sh by npm run sync-installer.",
  "// Do not edit this file directly.",
  `export const installer = ${JSON.stringify(installer)};`,
  "",
].join("\n");

await mkdir(dirname(outputPath), { recursive: true });
await writeFile(outputPath, generated, "utf8");
